import{auth}from"./firebase.js";import{forgeXModal}from"./utils.js";import{sendPasswordResetEmail}from"https://www.gstatic.com/firebasejs/10.7.1/firebase-auth.js";const resetForm=document.querySelector("form"),emailInput=document.getElementById("email"),resetButton=document.querySelector(".login-btn");resetForm&&emailInput&&resetButton&&resetForm.addEventListener("submit",async e=>{e.preventDefault(),resetButton.disabled=!0,resetButton.innerText="Folyamatban...";try{await sendPasswordResetEmail(auth,emailInput.value.trim()),await forgeXModal("Link elkuldve","Elkuldtuk a jelszo-visszaallito linket az email cimedre.")}catch(e){console.error("Password reset error:",e.code),await forgeXModal("Hiba tortent","A jelszo-visszaallitas most nem sikerult. Ellenorizd az email címet, majd probald ujra.")}finally{resetButton.disabled=!1,resetButton.innerText="Jelszo visszaallitasa"}});